/**
 * ARC-network market data — DexScreener public API snapshot.
 *
 * Discovery: GET /latest/dex/search?q= swept across ~950 keywords; every pair
 * whose chainId is 'arc' was kept (277 pairs), then reduced to one row per
 * token — its deepest-liquidity pool — and ranked on real 24h numbers.
 *
 * Endpoints used:
 *   GET /latest/dex/search?q=          pair discovery
 *   GET /tokens/v1/arc/{addresses}     batch lookup, 30 addresses per call
 *   GET /latest/dex/pairs/arc/{pair}   pair detail (token imagery, when set)
 * Docs: https://docs.dexscreener.com/api/reference
 *
 * Regenerate with:  node scripts/fetch-arc.mjs
 *
 *   ARC_TOP_VOLUME  — 50 highest 24h-volume ARC tokens
 *   ARC_TOP_MOVERS  — 50 largest 24h price moves
 *   ARC_GAINERS     — every ARC token up over 24h, best first
 *   ARC_LOSERS      — every ARC token down over 24h, worst first
 *   ARC_ALL         — all tracked ARC tokens, volume-sorted
 */

export type ArcTimeframe = "m5" | "h1" | "h6" | "h24";

export type ArcToken = {
  symbol: string;
  name: string;
  quote: string;
  pair: string;
  address: string;
  pairAddress: string;
  dex: string;
  price: number;
  change: Record<ArcTimeframe, number>;
  volume: Record<ArcTimeframe, number>;
  liquidity: number;
  fdv: number;
  marketCap: number;
  txns24: { buys: number; sells: number };
  createdAt: number | null;
  image: string | null;
  dexUrl: string;
};

export const ARC_CHAIN = "arc" as const;

