/** Aliases kept for the shared market components. */
export const ARC_HOT = ARC_TOP_VOLUME;
export const ARC_TOKENS = ARC_ALL;
export const ARC_NEW = [...ARC_ALL].sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0));

export const ARC_TOTAL_VOLUME_24H = ARC_ALL.reduce((s, t) => s + t.volume.h24, 0);
export const ARC_TOTAL_LIQUIDITY = ARC_ALL.reduce((s, t) => s + t.liquidity, 0);

/**
 * Every tracked token in one index, de-duplicated by pair address, so lookups
 * are not limited to whichever list happens to be first. The Trending, Gainers,
 * Losers and Volume lists overlap but each carries tokens the others miss.
 */
const ARC_LISTS: ArcToken[][] = [ARC_TRENDING, ARC_GAINERS, ARC_LOSERS, ARC_TOP_MCAP, ARC_TOP_VOLUME, ARC_ALL];

export const ARC_EVERY: ArcToken[] = (() => {
  const seen = new Map<string, ArcToken>();
  for (const list of ARC_LISTS) {
    for (const t of list) {
      const k = t.pairAddress.toLowerCase();
      if (!seen.has(k)) seen.set(k, t);
    }
  }
  return [...seen.values()];
})();

/** Resolve a pair address (as passed in ?pair=) to its token, from any list. */
export function findArcToken(pairAddress: string | null | undefined): ArcToken | undefined {
  if (!pairAddress) return undefined;
  const k = pairAddress.toLowerCase();
  return ARC_EVERY.find((t) => t.pairAddress.toLowerCase() === k) ?? ARC_EVERY.find((t) => t.address.toLowerCase() === k);
}

/** Same as findArcToken but never returns undefined. */
export function resolveArcToken(pairAddress: string | null | undefined): ArcToken {
  return findArcToken(pairAddress) ?? ARC_TRENDING[0];
}

export const ARC_TOKEN_COUNT = ARC_EVERY.length;
